const msg = $json.message || {};
const text = (msg.text || '').trim();
const chatId = String(msg.chat?.id || '');
const match = text.match(/^\/feed\s+(.+?)\s+(\d{1,4})\s*$/i);
if (/^\/help\b/i.test(text) || /^\/start\b/i.test(text)) return [{json:{chat_id:chatId,reply:'수유 기록: /feed 아이이름 120\n예: /feed 지온 120\n아이 이름은 앱에 등록된 이름과 같아야 해요.'}}];
if (!match) return [{json:{chat_id:chatId,reply:'명령을 확인해 주세요.\n/feed 아이이름 먹인양(ml)\n예: /feed 지온 120'}}];
const amount = Number(match[2]);
if (amount < 1 || amount > 1000) return [{json:{chat_id:chatId,reply:'먹인 양은 1~1000ml 범위로 입력해 주세요.'}}];
return [{json:{chat_id:chatId,child_name:match[1].trim(),amount_ml:amount,valid:true}}];

const prior = $('Parse command').item.json;
if ($json.error || $json.message) return [{json:{chat_id:prior.chat_id,reply:'기록하지 못했어요. 아이 이름과 Telegram 연결 설정을 확인해 주세요.'}}];
const row = Array.isArray($json) ? $json[0] : $json;
const when = row?.fed_at ? new Date(row.fed_at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul'}) : '';
const due = row?.next_due_at ? new Date(row.next_due_at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul'}) : '';
return [{json:{chat_id:prior.chat_id,reply:`${row?.child_name || prior.child_name}에게 ${row?.amount_ml || prior.amount_ml}ml 먹인 기록을 저장했어요. (${when})\n다음 알림 예정: ${due}`}}];
